static int nilfs_prepare_chunk(struct folio *folio, unsigned int from,
			       unsigned int to)
{
	loff_t pos = folio_pos(folio) + from;

	if (to > folio_size(folio) || from > to)
		return -EINVAL;

	return __block_write_begin(folio, pos, to - from, nilfs_get_block);
}

